mapper.select:
SELECT *
FROM (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t."comment_id") AS rn
        FROM (
            SELECT "comment_id", "user_id", "uname", "rating", "context", "create_time", "floor_id"
            FROM BOOKMAN."comments" left join BOOKMAN."user" on "comments"."user_id" = "user"."uid"
            where "book_id" = #{bookId}
            ) t
    ) rt
WHERE rt.rn >= #{start} AND rt.rn <= #{end}

SELECT *
FROM (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t."comment_id") AS rn
    FROM (
            SELECT "comment_id", "comments"."book_id", "rating", "context", "comments"."create_time", "floor_id"
            FROM BOOKMAN."comments" left join BOOKMAN."book" on "comments"."book_id" = "book"."book_id"
            where "user_id" = #{userId}
        ) t
) rt
WHERE rt.rn >= #{start} AND rt.rn <= #{end}
